// 命令接口：execute 执行，undo 回滚
interface Command {
    void execute();
    void undo();
}

// 接收者：真正干活的对象
class Light {
    void on()  { System.out.println("灯亮"); }
    void off() { System.out.println("灯灭"); }
    void setBrightness(int level) { System.out.println("亮度: " + level); }
}

// 简单命令：持有 Receiver，execute 调 on，undo 调 off
class LightOnCommand implements Command {
    private final Light light;
    LightOnCommand(Light light) { this.light = light; }
    public void execute() { light.on(); }
    public void undo()   { light.off(); }
}

// 带状态的命令：undo 需要恢复前一个状态
class SetBrightnessCommand implements Command {
    private final Light light;
    private final int newLevel;
    private int prevLevel; // 执行前快照，undo 用
    SetBrightnessCommand(Light light, int newLevel) {
        this.light = light;
        this.newLevel = newLevel;
    }
    public void execute() {
        prevLevel = /* 假设从 light 读取当前亮度 */ 50;
        light.setBrightness(newLevel);
    }
    public void undo() {
        light.setBrightness(prevLevel); // 恢复执行前状态
    }
}

// 宏命令：组合多个子命令，execute 正序，undo 逆序
import java.util.List;
class MacroCommand implements Command {
    private final List<Command> cmds;
    MacroCommand(List<Command> cmds) { this.cmds = cmds; }
    public void execute() { cmds.forEach(Command::execute); }
    public void undo() {
        for (int i = cmds.size() - 1; i >= 0; i--) cmds.get(i).undo();
    }
}

// 调用者：维护 undo 栈和 redo 栈
import java.util.ArrayDeque;
import java.util.Deque;
class Invoker {
    private final Deque<Command> undoStack = new ArrayDeque<>();
    private final Deque<Command> redoStack = new ArrayDeque<>();

    void submit(Command c) {
        c.execute();
        undoStack.push(c);
        redoStack.clear(); // 新操作清空 redo 栈：之前的 redo 历史已失效
    }

    void undo() {
        if (!undoStack.isEmpty()) {
            Command c = undoStack.pop();
            c.undo();
            redoStack.push(c);
        }
    }

    void redo() {
        if (!redoStack.isEmpty()) {
            Command c = redoStack.pop();
            c.execute();
            undoStack.push(c);
        }
    }
}

// 演示
public class CommandDemo {
    public static void main(String[] args) {
        Light light = new Light();
        Invoker invoker = new Invoker();

        invoker.submit(new LightOnCommand(light)); // 灯亮，压入 undo 栈
        invoker.undo();                             // 灯灭，命令移到 redo 栈
        invoker.redo();                             // 灯亮，命令移回 undo 栈

        // 宏命令：一次执行多个操作
        invoker.submit(new MacroCommand(List.of(
            new LightOnCommand(light),
            new SetBrightnessCommand(light, 80)
        )));
    }
}
